LITERATURE = [
    'Wolfgang Laur: Die Ortsnamen in Schaumburg. Schaumburger Studien 51, Rinteln 1993.',
    'Franz Engel: Die ländlichen Siedlungen in Schaumburg-Lippe und ihre Geschichte, in: Beiträge zur Siedlungsgeschichte und historischen Landeskunde, 1970.',
    'Helge bei der Wieden: Der Dreißigjährige Krieg in der Grafschaft Schaumburg: Schäden und ihre Beseitigung, in: Strukturen und Konjunkturen, Schaumburger Studien 63, 2004.',
    'Karl Heinz Schneider: Schaumburg in der Industrialisierung, Teil II: Von der Reichsgründung bis zum Ersten Weltkrieg, Schaumburger Studien 53, 1995.',
    'Ingrid und Werner Schütte: Das Eilser Minchen – Die Geschichte der Bad Eilsener Kleinbahn, 2. Auflage, Lübbecke 2001.',
]


def _population_chart() -> str:
    points = [(1821,220),(1836,237),(1871,378),(1905,624),(1912,682),(1937,880),(1950,1455),(1961,1047),(1967,940),(1985,1105),(1995,1165),(2007,1178),(2026,1022)]
    left, top, width, height = 56, 24, 680, 260
    min_year, max_year, max_pop = 1821, 2026, 1500
    coords = []
    for year, pop in points:
        x = left + (year-min_year)/(max_year-min_year)*width
        y = top + height - pop/max_pop*height
        coords.append((x,y,year,pop))
    path = " ".join(("M" if i == 0 else "L") + f"{x:.1f},{y:.1f}" for i,(x,y,_,_) in enumerate(coords))
    circles = "".join(f'<circle cx="{x:.1f}" cy="{y:.1f}" r="4"/><title>{year}: {pop} Einwohner</title>' for x,y,year,pop in coords)
    y_grid = "".join(f'<g><line x1="{left}" y1="{top+height-v/max_pop*height:.1f}" x2="{left+width}" y2="{top+height-v/max_pop*height:.1f}"/><text x="{left-10}" y="{top+height-v/max_pop*height+4:.1f}" text-anchor="end">{v}</text></g>' for v in (0,500,1000,1500))
    labels = "".join(f'<text x="{x:.1f}" y="{top+height+23}" text-anchor="middle">{year}</text>' for x,y,year,pop in coords if year in {1821,1871,1912,1950,1967,1995,2026})
    return f'''<div class="history-visual"><div class="history-visual-title">Bevölkerungsentwicklung · ausgewählte Stichtage</div><div class="history-chart"><svg viewBox="0 0 790 330" role="img" aria-label="Liniengrafik zur Bevölkerungsentwicklung Ahnsens"><g stroke="#d8e2d7" stroke-width="1" fill="none">{y_grid}</g><g fill="#647269" font-size="11">{labels}</g><path d="{path}" fill="none" stroke="#174936" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><g fill="#6f9d70" stroke="#fff" stroke-width="2">{circles}</g><text x="{coords[6][0]-10:.1f}" y="{coords[6][1]-16:.1f}" text-anchor="middle" fill="#174936" font-size="12" font-weight="800">1950 · 1.455</text><text x="{coords[-1][0]-4:.1f}" y="{coords[-1][1]-14:.1f}" text-anchor="end" fill="#174936" font-size="12" font-weight="800">2026 · 1.022</text></svg></div><div class="history-chart-note">Quellen wie im Bericht: Ortschronik für 1821–2008; Gemeindeseite für 2018; Samtgemeinde Eilsen für 2022; Statistikportal für 31.03.2026. Die Vergleichbarkeit ist wegen unterschiedlicher Stichtage, Erhebungsmethoden und der Eingliederung Widdensens 1929 eingeschränkt.</div></div>'''


def _timeline() -> str:
    return '<div class="history-timeline">' + ''.join(f'<div class="history-time"><div class="history-time-date">{date}</div><div class="history-time-rail"></div><div class="history-time-copy">{text}</div></div>' for date, text in TIMELINE) + '</div>'


def _visual_intro() -> str:
    cards = [
        ("stone", "Jungsteinzeit", "Steinbeilfunde in Neumühlen"),
        ("doc", "1256", "Adenhusen wird urkundlich genannt"),
        ("mill", "Mühlen", "Neumühlen prägt die Ortsgeschichte"),
        ("train", "1918–1966", "Das Eilser Minchen verbindet Ahnsen"),
    ]
    return '<div class="history-visual"><div class="history-visual-title">Vier sichtbare Epochen der Ortsgeschichte</div><div class="history-icon-row">' + ''.join(f'<div class="history-icon-card">{_svg(icon)}<strong>{title}</strong><small>{text}</small></div>' for icon,title,text in cards) + '</div></div>'


def history_content() -> str:
    toc = ''.join(f'<a href="#geschichte-{number}"><b>{number}</b><span>{title}</span></a>' for number,title,_ in CHAPTERS)
    toc += '<a href="#geschichte-18"><b>18</b><span>Bevölkerungsentwicklung im Langzeitblick</span></a><a href="#geschichte-19"><b>19</b><span>Zeitleiste</span></a><a href="#geschichte-20"><b>20</b><span>Quellen und Literatur</span></a>'
    chapters = []
    for number, title, body in CHAPTERS:
        chapters.append(f'<section class="history-chapter" id="geschichte-{number}"><div class="history-chapter-head"><span class="history-number">{number}</span><h2>{title}</h2></div>{body}<div class="history-top"><a href="#geschichte-inhalt">↑ Zum Inhaltsverzeichnis</a></div></section>')
    sources = ''.join(f'<div class="history-source"><b>[{number}]</b> {text} <a href="{url}" target="_blank" rel="noopener">Quelle öffnen</a></div>' for number,text,url in SOURCES)
    literature = ''.join(f'<div class="history-source">{item}</div>' for item in LITERATURE)
    return HISTORY_CSS + f'''
<div class="history-page" id="geschichte-oben">
<section class="history-hero"><a class="back-link" href="/">← Start</a><span class="history-kicker">Ortsgeschichte · Stand 7. August 2026</span><h1>Ahnsen<br>von den Anfängen bis heute</h1><p>Eine Ortsgeschichte von den frühesten Spuren bis 2026 – vollständig nach dem bereitgestellten Bericht, ergänzt um eine mobile Zeitleiste und eine grafische Bevölkerungsentwicklung.</p><div class="history-hero-art"><span>{_svg('stone')}</span><span>{_svg('doc')}</span><span>{_svg('mill')}</span><span>{_svg('train')}</span></div></section>
<div class="history-meta"><div><small>Erste bekannte Nennung</small><strong>1256 · Adenhusen</strong></div><div><small>Fläche</small><strong>3,43 km²</strong></div><div><small>Einwohner</small><strong>1.022</strong></div><div><small>Samtgemeinde</small><strong>Eilsen</strong></div></div>
<div class="history-note"><strong>Leseschlüssel:</strong> Der Bericht unterscheidet bewusst zwischen urkundlich oder archäologisch belegten Fakten und späteren heimatgeschichtlichen Rekonstruktionen. Zahlen in eckigen Klammern verweisen auf das Quellenverzeichnis am Ende.<br><br>Erstellt auf Grundlage der Ahnser Ortschronik, amtlicher Statistik und weiterer regionalhistorischer Quellen. Die Lagekarte der Originalausgabe zeigt Ahnsen im Landkreis Schaumburg; Karte: Wikimedia Commons, TUBS/Hagar66, CC BY bzw. Public-Domain-Freigaben – Details im Quellenverzeichnis.</div>
{_visual_intro()}
<section class="history-toc" id="geschichte-inhalt"><h2>Inhalt</h2><div class="history-toc-grid">{toc}</div></section>
{''.join(chapters)}
<section class="history-chapter" id="geschichte-18"><div class="history-chapter-head"><span class="history-number">18</span><h2>Bevölkerungsentwicklung im Langzeitblick</h2></div>{_population_chart()}<p>Die Langzeitreihe zeigt drei besonders auffällige Phasen. Erstens wuchs Ahnsen im 19. und frühen 20. Jahrhundert stark: von 220 Einwohnern 1821 auf 682 im Jahr 1912. Das entspricht dem Übergang von einer weitgehend agrarischen Siedlung zu einem Dorf mit Bergleuten, Handwerkern, Arbeitern und Gewerbebetrieben. [10,13]</p><p>Zweitens erzeugte die Flucht- und Vertreibungsbewegung nach 1945 einen außergewöhnlichen Ausschlag. 1950 wurden 1.455 Einwohner gezählt. Innerhalb weniger Jahre musste die Gemeinde hunderte Menschen zusätzlich unterbringen und versorgen. In den 1960er Jahren sank die Zahl wieder deutlich. [12,13]</p><p>Drittens folgte ab den 1970er Jahren eine lange Phase relativer Stabilität um 1.000 bis 1.180 Einwohner. Das Maximum der in der Chronik erfassten späteren Reihe lag 2007 bei 1.178. Zum 31. März 2026 waren es 1.022. Damit ist Ahnsen heute kleiner als vor zwanzig Jahren, aber weiterhin deutlich größer als das Dorf des 19. Jahrhunderts. [13,18]</p><div class="history-top"><a href="#geschichte-inhalt">↑ Zum Inhaltsverzeichnis</a></div></section>
<section class="history-chapter" id="geschichte-19"><div class="history-chapter-head"><span class="history-number">19</span><h2>Zeitleiste</h2></div>{_timeline()}<div class="history-top"><a href="#geschichte-inhalt">↑ Zum Inhaltsverzeichnis</a></div></section>
<section class="history-chapter" id="geschichte-20"><div class="history-chapter-head"><span class="history-number">20</span><h2>Quellen und Literatur</h2></div><p>Die folgenden Quellen bilden die Grundlage dieses Berichts. Die Nummern entsprechen den Verweisen im Text. Abrufdatum für Onlinequellen: 7. August 2026.</p><div class="history-sources">{sources}</div><h3>Weiterführende Literatur, die bereits in der Ortschronik ausgewertet wird</h3><div class="history-sources">{literature}</div><div class="history-top"><a href="#geschichte-inhalt">↑ Zum Inhaltsverzeichnis</a></div></section>
<section class="history-fazit"><h2>Fazit</h2><p>Ahnsens Geschichte beginnt nicht 1256 – dort beginnt nur die schriftliche Überlieferung. Aus einer kleinen Hofsiedlung am Rand alter Verkehrs- und Herrschaftsräume wurde ein Dorf mit Mühle, Handwerk, Bergleuten, Bahn und Industrie. Krieg, Diktatur, Flucht und Verwaltungsreformen hinterließen tiefe Spuren. Heute ist Ahnsen eine kleine, eigenständige Wohngemeinde in der Samtgemeinde Eilsen, deren Ortsbild und Flurnamen noch viele Schichten dieser mehr als 750 Jahre dokumentierten Geschichte bewahren.</p></section>
</div>'''
